<?php
require_once __DIR__.'/../_shared/admin-auth.php';
bp_cors('GET, OPTIONS');$adminId=(int)($_GET['admin_id']??0);$a=bp_admin($adminId);if(!$a||strtolower($a['role'])!=='super_admin'){http_response_code(403);echo json_encode(['status'=>'error','message'=>'Super Admin access required.']);exit;}$c=bp_admin_conn();
$materials=$c->query('SELECT lm.material_id id,"learning_material" content_type,lm.title,lm.type,lm.description,lm.link,lm.date_created,lm.admin_id,COALESCE(a.fullname,"Unknown") submitted_by,lm.approval_status,lm.rejection_reason,s.subject_name FROM learning_material lm LEFT JOIN admin a ON a.admin_id=lm.admin_id LEFT JOIN subject s ON s.subject_id=lm.subject_id WHERE lm.date_deleted IS NULL AND lm.approval_status="pending" ORDER BY lm.date_created DESC');
$quizzes=$c->query('SELECT q.quiz_id id,"quiz" content_type,q.quiz_title title,q.quiz_type,q.difficulty,q.date_created,q.admin_id,COALESCE(a.fullname,"Unknown") submitted_by,q.approval_status,q.rejection_reason,lm.title material_title FROM quiz q LEFT JOIN admin a ON a.admin_id=q.admin_id LEFT JOIN learning_material lm ON lm.material_id=q.material_id WHERE q.approval_status="pending" ORDER BY q.date_created DESC');$out=[];while($r=$materials->fetch_assoc())$out[]=$r;while($r=$quizzes->fetch_assoc())$out[]=$r;$c->close();echo json_encode(['status'=>'success','items'=>$out,'total'=>count($out)],JSON_UNESCAPED_UNICODE);
